let relevantGroups = [];
try {
  const parsed = JSON.parse($json.message?.content ?? '{}');
  relevantGroups = Array.isArray(parsed.relevantGroups) ? parsed.relevantGroups : [];
} catch (e) {
  relevantGroups = [];
}

// Single source of truth for the group -> tool mapping. Keep this in
// sync with skills-mcp/src/server.ts's tool registration when adding
// or removing a tool - a tool not added to a group here silently never
// gets exposed through chat, no error either way.
const GROUPS = {
  research: ['knowledge_search', 'knowledge_ingest', 'research_task', 'research_task_status', 'web_search'],
  personal: ['memory_recall', 'goal_manage'],
  automation: ['calendar_event', 'spotify_control', 'dashboard_control', 'weather_get'],
  'self-growth': ['skill_propose', 'code_task', 'code_task_status'],
};
// calculate is always included, not gated by classification - it's a
// single lightweight, side-effect-free tool, and relying on an LLM
// classifier to correctly spot every arithmetic-shaped message is the
// same class of unreliability this project has hit before. Cheap enough
// to just always offer it rather than hope the classifier catches it.
const tools = [...new Set(['calculate', 'task_context_manage', ...relevantGroups.flatMap(g => GROUPS[g] || [])])];
return [{ json: { relevantGroups, relevantTools: tools } }];

